                    '33280000',
                    file(params.modules_testdata_base_path + 'generic/config/pytmb_haplotc.yml', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'generic/config/pytmb_snpeff.yml', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(
                    process.out
                ).match() }
            )
        }

    }
